class Solution:
    def findClosestElements(self, arr: list[int], k: int, x: int) -> list[int]:
        lo, hi = 0, len(arr) - k           # the window [i, i + k) can start at 0 .. n - k
        while lo < hi:                     # O(log(n - k)) iterations
            mid = (lo + hi) // 2
            if x - arr[mid] > arr[mid + k] - x:
                lo = mid + 1               # arr[mid + k] is strictly closer: slide the window right
            else:
                hi = mid                   # ties keep the smaller values, so stay left
        return arr[lo:lo + k]              # O(k) to build the answer

